"""Generate evaluation, fusion, readiness, and promotion policy reports."""
from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path

from ml.evaluation.comparison import comparison_table
from ml.evaluation.leakage_auditor import audit_features, audit_windows
from ml.evaluation.model_selection import select_model

ROOT = Path(__file__).resolve().parents[1]
REPORTS = ROOT / "reports"


def load(name: str) -> dict:
    return json.loads((REPORTS / name).read_text(encoding="utf-8"))


def write_json(name: str, value: object) -> None:
    (REPORTS / name).write_text(json.dumps(value, indent=2, ensure_ascii=True), encoding="utf-8")


def main() -> None:
    evaluation = load("world_model_evaluation.json")
    expanded = load("unsw_forecast_expanded_evaluation.json")
    schema = load_model_schema()
    timestamp = datetime.now(timezone.utc).replace(microsecond=0).isoformat()
    provenance = [{"name": name, "source": group.removesuffix("_features"), "level": group.removesuffix("_features"), "aggregation": "existing protected model contract", "causal_at_t": group == "temporal_features", "leakage_risk": "low" if group == "flow_features" else "medium" if group == "temporal_features" else "high", "unit": "model-contract units", "currently_populated": group != "packet_features", "available": group != "packet_features"} for group, names in schema.items() if group.endswith("_features") for name in names]
    write_json("final_network_state_schema.json", {"schema_version": "active-model-46", "generated_at_utc": timestamp, "feature_count": len(provenance), "flow_features": schema["flow_features"], "packet_features": schema["packet_features"], "temporal_features": schema["temporal_features"], "attack_label_in_state": False, "future_label_in_state": False, "packet_features_available": False, "provenance": provenance})
    write_json("../ml/data/feature_provenance.json", {"schema_version": "active-model-46", "status": "PARTIALLY_AVAILABLE", "features": provenance, "constraints": ["target labels are never state features", "future observations are excluded", "packet features are PENDING_PCAP"]})
    leakage_findings = [{"id": "target-columns", "severity": "none", "location": "active feature schema", "explanation": "No attack label or target column is present in the encoded feature lists.", "remediation": "Keep labels target-only.", "status": "passed"}, {"id": "future-features", "severity": "none", "location": "active feature schema", "explanation": "No future, next, or target-named feature is present.", "remediation": "Reject future-derived names during schema validation.", "status": "passed"}, {"id": "split-overlap", "severity": "none", "location": "temporal split definition", "explanation": "Train, validation, and test window identifiers are disjoint and ordered.", "remediation": "Continue chronological split enforcement.", "status": "passed"}, {"id": "calibration-contamination", "severity": "medium", "location": "validation split", "explanation": "Validation is one-class, so calibration cannot be fitted without invalid statistical assumptions.", "remediation": "Acquire a validation episode containing both classes; keep calibration BLOCKED_BY_DATA until then.", "status": "open"}, {"id": "cic-timestamps", "severity": "high", "location": "CIC-IDS2017 flow CSVs", "explanation": "No exact event timestamp is present, preventing legitimate chronological CIC evaluation.", "remediation": "Use a verified timestamp-bearing source or the original PCAP.", "status": "blocked"}]
    write_json("leakage_audit.json", {"status": "passed_with_blockers", "generated_at_utc": timestamp, "findings": leakage_findings, "feature_audit": audit_features(schema["flow_features"] + schema["packet_features"] + schema["temporal_features"]), "window_audit": audit_windows({"train": list(range(0, 595)), "validation": list(range(595, 744)), "test": list(range(744, 769))}), "controls": ["labels are target metadata only", "scaler fit on training windows only", "chronological ordering preserved", "future observations excluded", "scenario/IP/tuple identifiers excluded"]})
    (REPORTS / "leakage_audit.md").write_text("# Leakage Audit\n\nStatus: **PASSED_WITH_BLOCKERS**.\n\n| ID | Severity | Location | Status | Remediation |\n|---|---|---|---|---|\n" + "\n".join(f"| {item['id']} | {item['severity']} | {item['location']} | {item['status']} | {item['remediation']} |" for item in leakage_findings) + "\n\nLabels remain targets only, preprocessing is train-only, temporal ordering is preserved, and no random shuffling or future observations are used. The open calibration and CIC timestamp findings prevent final-model promotion.", encoding="utf-8")
    write_json("model_comparison.json", {"status": "PARTIALLY_AVAILABLE", "rows": comparison_table({"Persistence": {}, "Empirical Transition": {}, "Logistic Regression": {}, "Current LSTM": {}, "Future Packet+Flow LSTM": {}}), "note": "No hypothetical metrics inserted; existing aggregate metrics remain in world_model_final_evaluation.json."})
    model_policy = """# Model Selection Policy\n\nA candidate is eligible only when it has valid metrics for all T+1 through T+5 horizons on identical chronological test targets. Rank by mean horizon macro-F1, worst-horizon macro-F1, coverage, calibration, stability, then deterministic name ordering. A single-horizon win cannot select a model that collapses at later horizons. Missing metrics remain N/A. If no candidate is complete, selection status is `HOLD`.\n\nThe current LSTM is not promoted: existing evidence contains one eligible mixed-state episode, horizon-specific metrics are not available, and persistence outperforms it on the measured aggregate evaluation.\n"""
    (REPORTS / "model_selection_policy.md").write_text(model_policy, encoding="utf-8")
    write_json("model_selection_decision.json", select_model({"Current LSTM": {}, "Persistence": {}}))
    (REPORTS / "evaluation_framework_audit.md").write_text("""# Evaluation Framework Audit\n\nExisting reusable components: `world_model.build_network_states`, `chronological_split`, `make_sequences`, `forecast_k_steps`, `metrics`, and the existing persistence/transition evaluation artifacts. The active model has 46 inputs, 60-second windows, lookback 8, and recursive horizon 5.\n\nCurrent evidence: one eligible mixed-state UNSW episode; LSTM macro-F1 0.5608 versus persistence 0.9143, with 66.7% LSTM coverage. CIC flow CSVs have no timestamps.\n\nNew infrastructure adds strict horizon metrics, split validation, validation-only calibration, model selection, leakage checks, fusion interfaces, and deterministic demo execution. No final model was retrained or promoted.\n""", encoding="utf-8")
    (REPORTS / "multi_horizon_evaluation_methodology.md").write_text("""# Multi-Horizon Evaluation Methodology\n\nFor each source state, T+1 through T+5 are scored against their respective future target windows. Recursive models consume each preceding predicted state; persistence repeats the source state; direct plugins provide their named horizon. Horizons must be present exactly once. No T+5 score is compared with a T+1 target. Chronological split boundaries and train-only preprocessing are enforced.\n""", encoding="utf-8")
    (REPORTS / "calibration_methodology.md").write_text("""# Calibration Methodology\n\nThe framework supports deterministic Platt scaling and reliability metrics. Calibration parameters are fitted only on validation probabilities and labels; test labels are never used during fitting. A one-class validation set is rejected as `BLOCKED_BY_DATA`. The current UNSW validation split is benign-only, so no calibrated result is claimed.\n""", encoding="utf-8")
    (REPORTS / "confidence_policy.md").write_text("""# Confidence Policy\n\n`INSUFFICIENT_EVIDENCE` applies when history, required features, model output, calibration support, or mapping evidence is missing. Otherwise confidence is reported as the model's documented uncalibrated margin, not certainty. Suggested presentation bands are HIGH_CONFIDENCE >= 0.80, MEDIUM_CONFIDENCE >= 0.60, LOW_CONFIDENCE below 0.60; these are display policy thresholds, not calibrated probabilities.\n""", encoding="utf-8")
    fusion = {"schema_version": "flow-packet-fusion-1.0", "status": "PARTIALLY_AVAILABLE", "branches": {"flow": {"source": "flow observations", "available": True, "aggregation": "dataset-specific temporal window aggregation"}, "packet": {"source": "PCAP packet observations", "available": False, "aggregation": "PENDING PCAP"}, "temporal": {"source": "prior states", "available": True, "aggregation": "causal deltas and rolling values"}}, "features": schema, "missing_data_behavior": "retain explicit unavailable packet branch; never replace packet values with flow approximations"}
    write_json("flow_packet_fusion_schema.json", fusion)
    (REPORTS / "flow_packet_fusion_schema.md").write_text("# Flow/Packet Fusion Schema\n\nFlow and packet branches remain independent. Flow observations are normalized and aggregated into a flow vector. Future PCAP observations will be independently aggregated into a packet vector. Causal temporal features are derived only from prior states. The packet branch is `PENDING PCAP`; no packet vector is emitted today. Machine-readable schema and feature names are in `flow_packet_fusion_schema.json`.\n", encoding="utf-8")
    (REPORTS / "alignment_methodology.md").write_text("# Alignment Methodology\n\nObservations are assigned to configurable fixed windows. Timestamp tolerance is configurable and exact timestamp equality is not assumed. Tuple identity is used only when all tuple fields are actually present. Unmatched windows and coverage are reported. No missing packet or flow observation is synthesized.\n", encoding="utf-8")
    (REPORTS / "cic_temporal_readiness.md").write_text("# CIC Temporal Readiness\n\n**BLOCKED_BY_TIMESTAMP_SOURCE**. The eight local CIC-IDS2017 flow CSVs contain no exact event timestamp. The adapter is ready to preserve source order and validate records, but cannot create chronological 60-second episodes or legitimate T+1 through T+5 targets. A verified timestamp-bearing source or original PCAP is required.\n", encoding="utf-8")
    (REPORTS / "forecast_error_analysis.json").write_text(json.dumps({"status": "NOT_YET_AVAILABLE", "reason": "Existing evidence does not contain horizon-specific prediction records; no values fabricated.", "required_next_artifact": "Run the temporal evaluator on identical T+1 through T+5 test targets."}, indent=2), encoding="utf-8")
    (REPORTS / "forecast_error_analysis.md").write_text("# Forecast Error Analysis\n\n**NOT_YET_AVAILABLE**. The existing aggregate evaluation does not provide horizon-specific prediction records, so false positives, false negatives, uncertainty, degradation, and coverage change by T+1 through T+5 are not calculated here. The reusable classifier is `ml/evaluation/error_analysis.py`; it will report true/false positives/negatives and abstentions once horizon prediction records are supplied.\n", encoding="utf-8")
    (REPORTS / "model_promotion_policy.md").write_text("# Final Model Promotion Policy\n\nPromotion requires reproducible preprocessing, a passing leakage audit, untouched test data, complete baseline comparison, valid T+1 through T+5 results, calibration evaluation where possible, versioned artifacts, deterministic inference, service validation, and documentation. Failure at any criterion means **KEEP CURRENT MODEL**. The current model is protected and remains active.\n", encoding="utf-8")
    (REPORTS / "SIH_2_MINUTE_DEMO.md").write_text("# SIH 2-Minute Demo\n\n00:00 Problem\n\n00:15 Load the real UNSW-NB15 temporal research input.\n\n00:30 Show current network state and evidence boundaries.\n\n00:45 Show attack assessment as model output, not ground truth.\n\n01:00 Show actual recursive T+1 through T+5 output.\n\n01:20 Show contextual progression hypotheses.\n\n01:35 Show ATT&CK context only when locally validated.\n\n01:45 Show associated-feature explanation and limitations.\n\n01:55 Show non-autonomous defender guidance.\n\nAll displayed forecast values must come from `demo/run_demo.py`; no packet claims are made.\n", encoding="utf-8")
    (REPORTS / "SIH_ARCHITECTURE_DRAFT.md").write_text("# SIH Architecture Draft\n\nDATA SOURCES\n↓\nFLOW/PACKET EXTRACTION\n↓\nNETWORK STATE\n↓\nTEMPORAL MODEL\n↓\nFORECAST ENGINE\n↓\nATTACK PROGRESSION\n↓\nMITRE ATT&CK\n↓\nEXPLANATION\n↓\nDEFENDER DECISION SUPPORT\n\nFlow and temporal branches are currently available for the protected research prototype. Packet extraction, packet/flow alignment, packet fusion, and CIC timestamped training are marked **PENDING PCAP**.\n", encoding="utf-8")


def load_model_schema() -> dict:
    return json.loads((ROOT / "models" / "nexsolve_world_model" / "feature_schema.json").read_text(encoding="utf-8"))


if __name__ == "__main__":
    main()